		{"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb", peerID, mcpValidationAssetID, "runs_on", nil},
		{"cccccccc-cccc-4ccc-8ccc-cccccccccccc", mcpValidationAssetID, peerID, "depends_on", time.Now().UTC()},
	} {
